<?php
declare(strict_types=1);require dirname(__DIR__,2).'/bootstrap.php';use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\StageDisplayService;Auth::requireAdmin();$pdo=Database::connection();$roundId=(int)($_GET['round_id']??0);$s=$pdo->prepare("SELECT r.*,e.name event_name FROM bdc_scoring_rounds r JOIN bdc_events e ON e.id=r.event_id WHERE r.id=:id LIMIT 1");$s->execute(['id'=>$roundId]);$round=$s->fetch();if(!$round){http_response_code(404);exit('Round not found.');}$csrf=Csrf::token();$stage=ucfirst((string)$round['round_type']);$types=$round['round_type']==='heats'?['judges'=>'Judges','competitors'=>'Competitors','scoring'=>'Scoring Status','callbacks'=>'Callback Reveal']:($round['round_type']==='semifinal'?['judges'=>'Judges','competitors'=>'Semifinal Competitors','scoring'=>'Scoring Status','finalists'=>'Finalists Reveal']:['judges'=>'Judges','competitors'=>'Final Couples / Finalists','scoring'=>'Scoring Status','results'=>'Final Ranking','winners'=>'Winner Reveal']);?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Projection Control | BDC</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f4f6f9}.project-card{border:0;border-radius:15px}.winner button{min-width:110px}</style></head><body><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="./">Live Screen Projector</a><a class="btn btn-outline-light btn-sm" href="../scoring/?mode=<?=e((string)($round['scoring_mode']??'manual'))?>&round_id=<?=$roundId?>">Back to Scoring</a></div></nav><main class="container py-4"><div class="mb-4"><div class="text-uppercase text-danger fw-bold small"><?=e(strtoupper($stage))?> PROJECTION CONTROL</div><h1 class="h2 mb-1"><?=e($round['event_name'])?></h1><div class="text-muted"><?=e(ucwords(str_replace('_',' ',$round['division'])))?> · <?=e($stage)?></div></div><div class="row g-3"><?php foreach($types as $key=>$label):?><div class="col-md-6"><div class="card project-card shadow-sm h-100"><div class="card-body"><h2 class="h5"><?=e($label)?></h2><p class="text-muted small">Audience-safe 9:16 screen for this <?=e(strtolower($stage))?> round.</p><?php if($key==='competitors'):?><form method="post" action="../stage-display-link.php" target="_blank"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="round_id" value="<?=$roundId?>"><input type="hidden" name="data_mode" value="real"><button class="btn btn-danger">Generate / Regenerate Link</button></form><?php else:?><a class="btn btn-outline-danger" href="projection.php?round_id=<?=$roundId?>&type=<?=e($key)?>" target="_blank">Open Projection</a><?php endif;?><?php if($key==='winners'):?><div class="winner d-flex flex-wrap gap-2 mt-3"><?php foreach([5,4,3,2,1] as $place):?><a class="btn btn-dark btn-sm" target="_blank" href="projection.php?round_id=<?=$roundId?>&type=winners&place=<?=$place?>">Reveal <?=$place?><?=match($place){1=>'st',2=>'nd',3=>'rd',default=>'th'}?></a><?php endforeach;?><a class="btn btn-warning btn-sm" target="_blank" href="projection.php?round_id=<?=$roundId?>&type=winners&place=all">Show All Top 5</a></div><?php endif;?></div></div></div><?php endforeach;?></div></main></body></html>